func PathEscape(pth string) string {
	// '#' and '?' are valid path characters but would otherwise be
	// interpreted as a fragment and query by url.Parse.
	pth = strings.NewReplacer("#", "%23", "?", "%3F").Replace(pth)
	u, err := url.Parse(pth)
	if err != nil {
		panic(err)
	}
	return u.EscapedPath()
}

